    public sealed class DayCoreTests
    {
        string root; readonly List<FileStateStore> stores=new List<FileStateStore>(); int sequence;
        [SetUp]public void Start(){root=Path.Combine(Path.GetTempPath(),"g3-core-"+Guid.NewGuid().ToString("N"));}
        [TearDown]public void End(){foreach(var s in stores)s.Dispose();if(Directory.Exists(root))Directory.Delete(root,true);}
        DayGameService Open(string name="normal",RunState state=null)
        {var store=new FileStateStore(Path.Combine(root,name),state??RunFactory.Create("run","g3-core-seed"));stores.Add(store);Assert.That(store.CanMutate,Is.True);return new DayGameService(store);}
        string Cmd()=>"test-"+(++sequence);static void Ok(CommandResult r){Assert.That(r.Success,Is.True,r.Code);StateInvariants.Validate(r.State);}
        static void Unchanged(DayGameService game,string expected,Func<CommandResult> action)
        {string hash=StateCodec.ComputeHash(game.Snapshot);var r=action();Assert.That(r.Code,Is.EqualTo(expected));Assert.That(r.CommitStatus,Is.EqualTo(CommitStatus.PROVEN_NOT_COMMITTED));Assert.That(StateCodec.ComputeHash(game.Snapshot),Is.EqualTo(hash));}
        [Test]public void NewNormalDayHasFrozenCashDebtInterestAndNoFixture()
        {var s=RunFactory.Create("first","seed");Assert.That(s.CashMinor,Is.EqualTo(30000));Assert.That(s.PrincipalMinor,Is.EqualTo(300000));Assert.That(s.InterestDueMinor,Is.EqualTo(1500));Assert.That(s.FixtureLabel,Is.Empty);Assert.That(s.DiagnosticChallengeArrangements,Is.Empty);Assert.That(s.Tools,Is.Empty);Assert.That(s.Drawers.All(x=>x==null),Is.True);Assert.That(s.NextToolIds.All(x=>x==""),Is.True);Assert.That(s.LifetimeEffectiveTickets,Is.Zero);}
        [Test]public void NormalSupplyIsDeterministicDistinctAndContainsEveryQualityWithoutChangingWeights()
        {
            Assert.That(DayRules.ShopRarityForSample(799999),Is.EqualTo("common"));Assert.That(DayRules.ShopRarityForSample(800000),Is.EqualTo("rare"));Assert.That(DayRules.ShopRarityForSample(994999),Is.EqualTo("rare"));Assert.That(DayRules.ShopRarityForSample(995000),Is.EqualTo("precious"));Assert.That(DayRules.ShopRarityForSample(999999),Is.EqualTo("precious"));
            Assert.That(DayRules.ConsumableQualityForSample(799999),Is.EqualTo("common"));Assert.That(DayRules.ConsumableQualityForSample(800000),Is.EqualTo("rare"));Assert.That(DayRules.ConsumableQualityForSample(989999),Is.EqualTo("rare"));Assert.That(DayRules.ConsumableQualityForSample(990000),Is.EqualTo("precious"));Assert.Throws<ArgumentOutOfRangeException>(()=>DayRules.ShopRarityForSample(1000000));Assert.Throws<ArgumentOutOfRangeException>(()=>DayRules.ConsumableQualityForSample(-1));
            string[] ids={"boost_coupon","seal_sticker","copy_paper","boost_coupon","copy_paper","reveal_film","reveal_film","seal_sticker","copy_paper","reveal_film","boost_coupon","seal_sticker"};
            int[] seeds={0,1,6,7,9,10,14,15,70,109,167,901};int[] qualities={0,0,0,1,1,1,0,1,2,2,2,2};
            for(int i=0;i<seeds.Length;i++)
            {string seed="g3-catalog-"+seeds[i];var s=RunFactory.Create("catalog",seed);Assert.That(StateCodec.ComputeHash(s),Is.EqualTo(StateCodec.ComputeHash(RunFactory.Create("catalog",seed))));
                Assert.That(s.Stock.Take(2).All(x=>!x.IsConsumable&&x.Quality=="common"),Is.True);Assert.That(s.Stock.Select(x=>x.ItemId).Distinct().Count(),Is.EqualTo(4));var consumable=s.Stock.Single(x=>x.IsConsumable);Assert.That(consumable.ItemId,Is.EqualTo(ids[i]));Assert.That(consumable.Quality,Is.EqualTo(DayRules.Qualities[qualities[i]]));Assert.That(s.ConsumableBatch.Distinct().Count(),Is.EqualTo(4));}
            Assert.That(RunFactory.Create("catalog","g3-catalog-14").Stock[2].ItemId,Is.EqualTo("alternating_stamp"));Assert.That(RunFactory.Create("catalog","g3-catalog-451").Stock[2].ItemId,Is.EqualTo("last_tickets_stamp"));
        }
        [Test]public void BrowsingAndCopyingCannotRefreshSupplyOrConsumeRandomness()
        {var g=Open();string hash=StateCodec.ComputeHash(g.Snapshot);for(int i=0;i<20;i++){g.PreviewNightBill();g.PreviewSettlement();var s=g.Snapshot;s.Stock.Clear();}Assert.That(StateCodec.ComputeHash(g.Snapshot),Is.EqualTo(hash));}
        [Test]public void NumberAndChallengeUseSeparatePersistentStreams()
        {var a=Open("a");var b=Open("b");Ok(a.BuyChallengeTicket(Cmd(),a.Snapshot.Revision));var t=a.Snapshot.CurrentTicket;int danger=Array.FindIndex(t.ChallengeSafe,x=>!x);Ok(a.SelectChallengeCell(t.Id,danger,Cmd(),a.Snapshot.Revision));Ok(a.QuickReveal(t.Id,Cmd(),a.Snapshot.Revision));Ok(a.Claim(t.Id,Cmd(),a.Snapshot.Revision));Ok(a.BuyNumberTicket(Cmd(),a.Snapshot.Revision));Ok(b.BuyNumberTicket(Cmd(),b.Snapshot.Revision));Assert.That(a.Snapshot.CurrentTicket.RawPrizeMinor,Is.EqualTo(b.Snapshot.CurrentTicket.RawPrizeMinor));Assert.That(a.Snapshot.EconomicCounter,Is.EqualTo(b.Snapshot.EconomicCounter));Assert.That(a.Snapshot.ChallengeCounter,Is.GreaterThan(0));Assert.That(b.Snapshot.ChallengeCounter,Is.Zero);}
        [Test]public void EveryVisibleCellClipsBrushAtEveryEdgeWithoutNeighborLeak()
        {foreach(int count in new[]{6,8})for(int cell=0;cell<count;cell++)foreach(double u in new[]{0.0,1.0})foreach(double v in new[]{0.0,1.0}){var mask=new TicketMask(count);Assert.That(mask.Apply(new[]{new CellStroke(cell,u,v,u,v,false,.25,.25)}),Is.True);for(int other=0;other<count;other++){if(other==cell)Assert.That(mask.CellRevealedPixels(other),Is.GreaterThan(0));else Assert.That(mask.CellRevealedPixels(other),Is.EqualTo(0),"count="+count+" cell="+cell+" other="+other);}}}
        [Test]public void CellStrokeBatchRejectsOutOfBoundsAndWrongChallengeCellBeforeAnyChange()
        {var mask=new TicketMask(8);byte[] before=mask.ToBytes();Assert.Throws<ArgumentException>(()=>mask.Apply(new[]{new CellStroke(1,0,0,.5,.5,false,.1,.1),new CellStroke(1,0,0,1.01,.5,false,.1,.1)},1));Assert.That(mask.ToBytes(),Is.EqualTo(before));Assert.Throws<ArgumentException>(()=>mask.Apply(new[]{new CellStroke(2,0,0,.5,.5,false,.1,.1)},1));Assert.That(mask.ToBytes(),Is.EqualTo(before));}
        [Test]public void ChangedCellNeverCreatesAConnectingScratchSegment()
        {var mask=new TicketMask(6);mask.Apply(new[]{new CellStroke(0,0,0,1,.5,false,.02,.05),new CellStroke(2,0,0,0,.5,false,.02,.05)});Assert.That(mask.CellRevealedPixels(1),Is.Zero);Assert.That(mask.CellRevealedPixels(3),Is.Zero);Assert.That(mask.CellRevealedPixels(4),Is.Zero);Assert.That(mask.CellRevealedPixels(5),Is.Zero);}
        [Test]public void ChallengeRequiresSelectionAndAtLeastOneActualReveal()
        {var g=Open();Ok(g.BuyChallengeTicket(Cmd(),0));string t=g.Snapshot.CurrentTicket.Id;Unchanged(g,"SELECT_CELL_FIRST",()=>g.QuickReveal(t,Cmd(),g.Snapshot.Revision));Unchanged(g,"NOT_READY_TO_CLAIM",()=>g.Claim(t,Cmd(),g.Snapshot.Revision));int safe=Array.FindIndex(g.Snapshot.CurrentTicket.ChallengeSafe,x=>x);Ok(g.SelectChallengeCell(t,safe,Cmd(),g.Snapshot.Revision));Unchanged(g,"REVEAL_PENDING",()=>g.Claim(t,Cmd(),g.Snapshot.Revision));Unchanged(g,"REVEAL_PENDING",()=>g.SelectChallengeCell(t,(safe+1)%8,Cmd(),g.Snapshot.Revision));Unchanged(g,"REVEAL_PENDING",()=>g.Borrow("mother",1000,Cmd(),g.Snapshot.Revision));Ok(g.QuickReveal(t,Cmd(),g.Snapshot.Revision));Assert.That(g.Snapshot.CurrentTicket.SafeCount,Is.EqualTo(1));Assert.That(g.Snapshot.CurrentTicket.SelectedCell,Is.EqualTo(-1));Assert.That(g.Snapshot.CurrentTicket.RevealedCells.Count(x=>x),Is.EqualTo(1));Ok(g.Claim(t,Cmd(),g.Snapshot.Revision));Assert.That(g.Snapshot.Settlements.Single().TotalMinor,Is.EqualTo(1000));}
        [Test]public void ChallengeQuickRevealCompletesOnlyTheSelectedCell()
        {var g=Open();Ok(g.BuyChallengeTicket(Cmd(),0));var t=g.Snapshot.CurrentTicket;int safe=Array.FindIndex(t.ChallengeSafe,x=>x);Ok(g.SelectChallengeCell(t.Id,safe,Cmd(),g.Snapshot.Revision));Ok(g.QuickReveal(t.Id,Cmd(),g.Snapshot.Revision));Assert.That(g.Snapshot.CurrentTicket.Scratch.RevealedCellCount,Is.EqualTo(1));Unchanged(g,"SELECT_CELL_FIRST",()=>g.QuickReveal(t.Id,Cmd(),g.Snapshot.Revision));Unchanged(g,"INVALID_CELL",()=>g.SelectChallengeCell(t.Id,safe,Cmd(),g.Snapshot.Revision));}
        [Test]public void ChallengeSixSafeCellsStopFurtherChoicesAndPayFrozenTopStep()
        {var g=Open();Ok(g.BuyChallengeTicket(Cmd(),0));var t=g.Snapshot.CurrentTicket;foreach(int cell in Enumerable.Range(0,8).Where(i=>t.ChallengeSafe[i])){Ok(g.SelectChallengeCell(t.Id,cell,Cmd(),g.Snapshot.Revision));Ok(g.QuickReveal(t.Id,Cmd(),g.Snapshot.Revision));}Assert.That(g.Snapshot.CurrentTicket.RawPrizeMinor,Is.EqualTo(18000));Unchanged(g,"CHALLENGE_FINISHED",()=>g.SelectChallengeCell(t.Id,Array.FindIndex(t.ChallengeSafe,x=>!x),Cmd(),g.Snapshot.Revision));Ok(g.Claim(t.Id,Cmd(),g.Snapshot.Revision));Assert.That(g.Snapshot.CashMinor,Is.EqualTo(47000));}
        [Test]public void PartialChallengeMaskAndSelectionPersistAcrossColdStoreReopen()
        {var g=Open();Ok(g.BuyChallengeTicket(Cmd(),0));var t=g.Snapshot.CurrentTicket;Ok(g.SelectChallengeCell(t.Id,3,Cmd(),g.Snapshot.Revision));Ok(g.ApplyCellScratch(t.Id,new[]{new CellStroke(3,.1,.1,.3,.3,true,.04,.04)},Cmd(),g.Snapshot.Revision));byte[] mask=g.Snapshot.CurrentTicket.Scratch.ToBytes();string hash=StateCodec.ComputeHash(g.Snapshot);g.Dispose();g=Open();Assert.That(StateCodec.ComputeHash(g.Snapshot),Is.EqualTo(hash));Assert.That(g.Snapshot.CurrentTicket.SelectedCell,Is.EqualTo(3));Assert.That(g.Snapshot.CurrentTicket.Scratch.ToBytes(),Is.EqualTo(mask));Ok(g.QuickReveal(t.Id,Cmd(),g.Snapshot.Revision));Assert.That(g.Snapshot.CurrentTicket.RevealedCells[3],Is.True);}
        [Test]public void BorrowReplayDoesNotDuplicateCashAndRepaymentDoesNotRestoreLifetimeQuota()
        {var g=Open();string id=Cmd();Ok(g.Borrow("mother",20000,id,0));Ok(g.Borrow("mother",20000,id,0));Assert.That(g.Snapshot.CashMinor,Is.EqualTo(50000));Assert.That(g.Snapshot.Loans.Count,Is.EqualTo(1));Ok(g.RepayLoan("mother",10000,Cmd(),g.Snapshot.Revision));Assert.That(LoanRules.RemainingLimit(g.Snapshot,"mother"),Is.EqualTo(30000));Assert.That(g.Snapshot.Loans.Single().RemainingMinor,Is.EqualTo(10000));Unchanged(g,"LOAN_LIMIT",()=>g.Borrow("mother",30001,Cmd(),g.Snapshot.Revision));}
        [Test]public void ContactLoansHaveIndependentLimitsDeadlinesAndExactCustomAmounts()
        {var g=Open();Ok(g.Borrow("mother",50000,Cmd(),0));Ok(g.Borrow("girlfriend",1234,Cmd(),g.Snapshot.Revision));Assert.That(g.Snapshot.Loans[0].DueNight,Is.EqualTo(7));Assert.That(g.Snapshot.Loans[1].DueNight,Is.EqualTo(4));Assert.That(g.Snapshot.PhoneEvents.Select(x=>x.AmountMinor),Is.EqualTo(new long[]{50000,1234}));Assert.That(LoanRules.RemainingLimit(g.Snapshot,"mother"),Is.Zero);Assert.That(LoanRules.RemainingLimit(g.Snapshot,"girlfriend"),Is.EqualTo(28766));}
        [Test]public void RepaymentUsesEarliestDueAndCannotOverpayOrCreateMoney()
        {var g=Open();Ok(g.Borrow("mother",1000,"a",0));Ok(g.Borrow("mother",2000,"b",g.Snapshot.Revision));Ok(g.RepayLoan("mother",1500,Cmd(),g.Snapshot.Revision));Assert.That(g.Snapshot.Loans[0].RemainingMinor,Is.Zero);Assert.That(g.Snapshot.Loans[1].RemainingMinor,Is.EqualTo(1500));Unchanged(g,"REPAY_EXCEEDS_DEBT",()=>g.RepayLoan("mother",1501,Cmd(),g.Snapshot.Revision));Unchanged(g,"INVALID_AMOUNT",()=>g.Borrow("mother",0,Cmd(),g.Snapshot.Revision));Unchanged(g,"INVALID_AMOUNT",()=>g.RepayLoan("mother",-1,Cmd(),g.Snapshot.Revision));}
        [Test]public void DueNightIsActionableAndNextMorningFreezeIsPerContact()
        {var g=Open();Ok(g.Borrow("mother",1000,Cmd(),0));var s=g.Snapshot;Assert.That(LoanRules.IsFrozen(s,"mother",7),Is.False);Assert.That(LoanRules.IsFrozen(s,"mother",8),Is.True);Assert.That(LoanRules.IsFrozen(s,"girlfriend",8),Is.False);Ok(g.RepayLoan("mother",1000,Cmd(),g.Snapshot.Revision));Assert.That(LoanRules.IsFrozen(g.Snapshot,"mother",8),Is.False);Assert.That(LoanRules.RemainingLimit(g.Snapshot,"mother"),Is.EqualTo(49000));}
        [Test]public void IntradayPrincipalRepaymentNeverRefundsLockedInterest()
        {var g=Open();Ok(g.RepayPrincipal(3000,Cmd(),0));Assert.That(g.Snapshot.CashMinor,Is.EqualTo(27000));Assert.That(g.Snapshot.PrincipalMinor,Is.EqualTo(297000));Assert.That(g.PreviewNightBill().InterestUnpaidMinor,Is.EqualTo(1500));Assert.That(g.PreviewNightBill().NextDayInterestMinor,Is.EqualTo(1485));Unchanged(g,"G3_FULL_CLEAR_BOUNDARY",()=>g.RepayPrincipal(297000,Cmd(),g.Snapshot.Revision));}
        [Test]public void CumulativePrincipalScheduleSubtractsPreviouslyPaidAndInterestRoundsHalfUp()
        {Assert.That(DayRules.PrincipalDue(1,0),Is.Zero);Assert.That(DayRules.PrincipalDue(6,10000),Is.EqualTo(20000));Assert.That(DayRules.PrincipalDue(12,30000),Is.EqualTo(120000));Assert.That(DayRules.PrincipalDue(18,150000),Is.EqualTo(150000));Assert.That(DayRules.PrincipalDue(6,40000),Is.Zero);Assert.That(DayRules.Interest(100),Is.EqualTo(1));Assert.That(DayRules.Interest(99),Is.Zero);Assert.That(DayRules.Ratio(1,1,2),Is.EqualTo(1));}
        [Test]public void ActiveTicketBlocksEarlyCloseAndDayNeverAdvancesOnPreview()
        {var g=Open();Ok(g.BuyNumberTicket(Cmd(),0));Unchanged(g,"UNSETTLED_TICKET",()=>g.BeginClosing(Cmd(),g.Snapshot.Revision));Unchanged(g,"TICKET_OCCUPIED",()=>g.BuyChallengeTicket(Cmd(),g.Snapshot.Revision));long revision=g.Snapshot.Revision;for(int i=0;i<5;i++)g.PreviewNightBill();Assert.That(g.Snapshot.Revision,Is.EqualTo(revision));Assert.That(g.Snapshot.DayNumber,Is.EqualTo(1));}
        [Test]public void EarlyCloseAllowsLastShoppingButNightDisablesProcurement()
        {var g=Open();string stock=g.Snapshot.Stock.First(x=>!x.IsConsumable).StockId;Ok(g.BeginClosing(Cmd(),0));Unchanged(g,"DAY_CLOSED",()=>g.BuyNumberTicket(Cmd(),g.Snapshot.Revision));Ok(g.BuyStock(stock,"",Cmd(),g.Snapshot.Revision));Ok(g.EnterNightBill(Cmd(),g.Snapshot.Revision));Unchanged(g,"SHOP_CLOSED",()=>g.BuyStock(g.Snapshot.Stock.First(x=>x.IsConsumable).StockId,"",Cmd(),g.Snapshot.Revision));Ok(g.PayNightBill(false,Cmd(),g.Snapshot.Revision));Assert.That(g.Snapshot.DayNumber,Is.EqualTo(1));Assert.That(g.Snapshot.Phase,Is.EqualTo(DayPhase.DAY_COMPLETE));}
        [Test]public void InsufficientNightBillRequiresSeparateFailureConfirmationWithoutPartialDebit()
        {var g=Open();Ok(g.RepayPrincipal(29000,Cmd(),0));Ok(g.BeginClosing(Cmd(),g.Snapshot.Revision));Ok(g.EnterNightBill(Cmd(),g.Snapshot.Revision));Unchanged(g,"INSUFFICIENT_CASH",()=>g.PayNightBill(false,Cmd(),g.Snapshot.Revision));Assert.That(g.Snapshot.Phase,Is.EqualTo(DayPhase.NIGHT_BILL));Ok(g.PayNightBill(true,Cmd(),g.Snapshot.Revision));Assert.That(g.Snapshot.CashMinor,Is.EqualTo(1000));Assert.That(g.Snapshot.InterestPaidMinor,Is.Zero);Assert.That(g.Snapshot.Phase,Is.EqualTo(DayPhase.RUN_FAILED));}
        [Test]public void NightRescueBorrowingCanPayBillWithoutPrematureFailure()
        {var g=Open();Ok(g.RepayPrincipal(29500,Cmd(),0));Ok(g.BeginClosing(Cmd(),g.Snapshot.Revision));Ok(g.EnterNightBill(Cmd(),g.Snapshot.Revision));Assert.That(g.PreviewNightBill().ShortfallMinor,Is.EqualTo(1000));Ok(g.Borrow("girlfriend",1000,Cmd(),g.Snapshot.Revision));Ok(g.PayNightBill(false,Cmd(),g.Snapshot.Revision));Assert.That(g.Snapshot.CashMinor,Is.Zero);Assert.That(g.Snapshot.Loans.Single().RemainingMinor,Is.EqualTo(1000));Assert.That(g.Snapshot.Phase,Is.EqualTo(DayPhase.DAY_COMPLETE));}
        [Test]public void RestartResetsRunResourcesButKeepsUniqueEffectiveLifetimeProgress()
        {var g=Open();Ok(g.BuyNumberTicket(Cmd(),0));string t=g.Snapshot.CurrentTicket.Id;Ok(g.QuickReveal(t,Cmd(),g.Snapshot.Revision));Ok(g.Claim(t,Cmd(),g.Snapshot.Revision));Ok(g.Borrow("mother",1000,Cmd(),g.Snapshot.Revision));Ok(g.BeginClosing(Cmd(),g.Snapshot.Revision));Ok(g.EnterNightBill(Cmd(),g.Snapshot.Revision));Ok(g.PayNightBill(false,Cmd(),g.Snapshot.Revision));string restartId=Cmd();long restartRevision=g.Snapshot.Revision;Ok(g.RestartDay("new-run","new-seed",restartId,restartRevision));string restartedHash=StateCodec.ComputeHash(g.Snapshot);Ok(g.RestartDay("new-run","new-seed",restartId,restartRevision));Assert.That(StateCodec.ComputeHash(g.Snapshot),Is.EqualTo(restartedHash));var s=g.Snapshot;Assert.That(s.CashMinor,Is.EqualTo(30000));Assert.That(s.PrincipalMinor,Is.EqualTo(300000));Assert.That(s.Loans,Is.Empty);Assert.That(s.Tickets,Is.Empty);Assert.That(s.LifetimeEffectiveTickets,Is.EqualTo(1));Assert.That(s.LifetimeEffectiveAtOpen,Is.EqualTo(1));Assert.That(s.Contacts.All(x=>x.BorrowedLifetimeMinor==0),Is.True);Assert.That(s.Stock.All(x=>x.Quantity==1),Is.True);}
        [Test]public void ClaimThenBuyBindsIntentParametersAndBothEconomicEffectsExactlyOnce()
        {var g=Open();Ok(g.BuyNumberTicket(Cmd(),0));string t=g.Snapshot.CurrentTicket.Id;Ok(g.QuickReveal(t,Cmd(),g.Snapshot.Revision));long before=g.Snapshot.CashMinor,prize=g.Snapshot.CurrentTicket.RawPrizeMinor,rev=g.Snapshot.Revision;Ok(g.ClaimThenBuy(t,"challenge",-1,"parent",rev));Assert.That(g.Snapshot.CashMinor,Is.EqualTo(before+prize-1000));Assert.That(g.Snapshot.CurrentTicket.TicketType,Is.EqualTo("challenge"));string hash=StateCodec.ComputeHash(g.Snapshot);Ok(g.ClaimThenBuy(t,"challenge",-1,"parent",rev));Assert.That(StateCodec.ComputeHash(g.Snapshot),Is.EqualTo(hash));Unchanged(g,"COMMAND_ID_REUSED",()=>g.ClaimThenBuy(t,"number",-1,"parent",rev));Assert.That(g.Snapshot.Settlements.Count,Is.EqualTo(1));}
        [Test]public void FailedNextPurchaseKeepsClaimAndCanOnlyResumeOrExplicitlyCancelBoundIntent()
        {var g=Open(state:RunFactory.CreateDiagnostic("run"));Ok(g.BuyNumberTicket(Cmd(),0));string t=g.Snapshot.CurrentTicket.Id;Ok(g.QuickReveal(t,Cmd(),g.Snapshot.Revision));long before=g.Snapshot.CashMinor;var r=g.ClaimThenBuy(t,"number",0,"parent",g.Snapshot.Revision);Assert.That(r.Code,Is.EqualTo("DRAWER_EMPTY"));Assert.That(g.Snapshot.CashMinor,Is.EqualTo(before+5000));Assert.That(g.Snapshot.Settlements.Count,Is.EqualTo(1));Unchanged(g,"NEXT_PURCHASE_INTENT_PENDING",()=>g.BuyChallengeTicket(Cmd(),g.Snapshot.Revision));Ok(g.CancelNextPurchase("parent",Cmd(),g.Snapshot.Revision));Ok(g.BuyChallengeTicket(Cmd(),g.Snapshot.Revision));Assert.That(g.ResumeClaimThenBuy("parent").Code,Is.EqualTo("INTENT_CANCELLED"));}
        [Test]public void TwelveTicketContinuousCellStrokesRecordActualJournalSizeAndElapsedTime()
        {
            var g=Open();var timer=System.Diagnostics.Stopwatch.StartNew();long maxBytes=0;int accepted=0,noChange=0;
            for(int ticket=0;ticket<12;ticket++)
            {
                Ok(g.BuyNumberTicket(Cmd(),g.Snapshot.Revision));string id=g.Snapshot.CurrentTicket.Id;
                for(int cell=0;cell<6;cell++)for(int line=0;line<=12;line++)
                {
                    if(g.Snapshot.CurrentTicket.Scratch.CellCoverage(cell)==1)break;
                    double v=line/12.0;var result=g.ApplyCellScratch(id,new[]{new CellStroke(cell,0,v,1,v,true,.06,.06)},Cmd(),g.Snapshot.Revision);
                    if(result.Success){accepted++;maxBytes=Math.Max(maxBytes,StateCodec.SerializeCanonical(result.State).Length);}
                    else{Assert.That(result.Code,Is.EqualTo("NO_CHANGE"));noChange++;}
                }
                Assert.That(g.Snapshot.CurrentTicket.Scratch.IsFullyRevealed,Is.True);Ok(g.Claim(id,Cmd(),g.Snapshot.Revision));
            }
            timer.Stop();var state=g.Snapshot;long bytes=StateCodec.SerializeCanonical(state).Length;
            Assert.That(state.TicketsPurchasedToday,Is.EqualTo(12));Assert.That(state.Settlements.Count,Is.EqualTo(12));Assert.That(accepted,Is.GreaterThan(500));Assert.That(bytes,Is.LessThan(14*1024*1024));
            TestContext.WriteLine("G3_SCRATCH_STRESS_REPORT {\"tickets\":12,\"accepted_scratch_commands\":"+accepted+",\"no_change_batches\":"+noChange+",\"all_commands\":"+state.Commands.Count+",\"state_bytes\":"+bytes+",\"maximum_observed_state_bytes\":"+Math.Max(bytes,maxBytes)+",\"elapsed_ms\":"+timer.ElapsedMilliseconds+",\"scope\":\"Unity EditMode same production service/store; not phone performance\"}");
        }
        [Test]public void InvariantsRejectCorruptedPrizeCounterSnapshotAndLedger()
        {var g=Open();Ok(g.BuyNumberTicket(Cmd(),0));var s=g.Snapshot;s.CurrentTicket.RawPrizeMinor=1000000;Assert.Throws<InvalidOperationException>(()=>StateInvariants.Validate(s));s=g.Snapshot;s.EconomicCounter++;Assert.Throws<InvalidOperationException>(()=>StateInvariants.Validate(s));s=g.Snapshot;s.CashMinor++;Assert.Throws<InvalidOperationException>(()=>StateInvariants.Validate(s));s=g.Snapshot;s.CurrentTicket.ConfigurationSnapshot=new[]{new ToolSnapshot{ItemId="copy_base",Level=1}};Assert.Throws<InvalidOperationException>(()=>StateInvariants.Validate(s));}
    }
